// conductor_client.mjs — a typed client for code-conductor's /mcp server.
//
// Generated by code-conductor from its MCP tool registry at every boot; do not
// edit: the file is overwritten. Needs Node 18+ (global fetch) and nothing
// else. Contract: docs/mcp-applications.md → Client libraries.

if (typeof fetch !== 'function') throw new Error('conductor_client.mjs needs Node 18 or newer (global fetch)');

export const DEFAULT_URL = 'http://127.0.0.1:8787/mcp';

/**
 * A refusal or a fault from cc. `status` is the HTTP status: 200 for a tool's
 * own refusal, 4xx/5xx for a protocol fault. `code` is null when the response
 * was not JSON.
 */
export class ConductorError extends Error {
  /**
   * @param {string|null} code
   * @param {string} reason
   * @param {number} status
   * @param {*} body
   */
  constructor(code, reason, status, body) {
    super(`${code}: ${reason} (HTTP ${status})`);
    this.name = 'ConductorError';
    this.code = code;
    this.reason = reason;
    this.status = status;
    this.body = body;
  }
}

/**
 * @typedef {Object} MakeThingResultOwner
 * @property {string} name
 */

/**
 * @typedef {Object} MakeThingResultPartsItem
 * @property {number} at
 */

/**
 * @typedef {Object} MakeThingResultPolicyVariant2
 * @property {number} limit
 */

/**
 * @typedef {Object} MakeThingResult
 * @property {string} id
 * @property {string} [note]
 * @property {(number|null)} size
 * @property {(MakeThingResultOwner|null)} owner
 * @property {("open"|"closed"|null)} state
 * @property {true} ok
 * @property {Array<MakeThingResultPartsItem>} parts
 * @property {Object<string, number>} scores
 * @property {Object<string, *>} meta - Pass-through metadata.
 * @property {(string|number|boolean|null)} pin
 * @property {("allow"|"deny"|MakeThingResultPolicyVariant2)} policy
 * @property {*} input - Anything at all.
 */

/**
 * @typedef {Object} PickOneResultVariant1
 * @property {"a"} picked
 * @property {string} a
 */

/**
 * @typedef {Object} PickOneResultVariant2
 * @property {"b"} picked
 */

/** @typedef {(PickOneResultVariant1|PickOneResultVariant2)} PickOneResult */

/** One cc /mcp endpoint. Calls are attributed to the session the URL names. */
export class ConductorClient {
  /** @param {string} [url] */
  constructor(url) {
    this.url = (url || process.env.CONDUCTOR_MCP_URL || DEFAULT_URL).replace(/\/+$/, '');
  }

  /**
   * Call any tool by name, plugin tools included; resolves to the parsed JSON body.
   * @param {string} name
   * @param {Object<string, *>} [args]
   * @returns {Promise<*>}
   */
  async call(name, args = {}) {
    const res = await fetch(`${this.url}/tools/${encodeURIComponent(name)}`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(args),
    });
    const text = await res.text();
    let body;
    try { body = JSON.parse(text); }
    catch { throw new ConductorError(null, 'response is not JSON', res.status, text); }
    const obj = body !== null && typeof body === 'object' && !Array.isArray(body) ? body : null;
    if (res.status >= 400 || obj?.ok === false) {
      throw new ConductorError(obj?.code ?? null, obj?.reason ?? `HTTP ${res.status}`, res.status, body);
    }
    return body;
  }

  /**
   * Make a thing.
   * A second line with a """ triple quote, a *\/ comment end and a \ backslash.
   *
   * @param {Object} args
   * @param {string} args.name - The thing's name.
   * @param {number} [args.count] - How many. (default: 3)
   * @param {(string|null)} [args.label] - A label, or null to clear it.
   * @param {("small"|"large")} [args.kind] - Which kind.
   * @param {Object<string, *>} [args.extra] - Free-form {key: value} pairs.
   * @param {string} [args.from] - Where it comes from.
   * @param {Array<string>} [args.tags]
   * @returns {Promise<MakeThingResult>}
   */
  make_thing(args) {
    return this.call('make_thing', args);
  }

  /**
   * Pick one.
   *
   * @param {Object} [args]
   * @returns {Promise<PickOneResult>}
   */
  pick_one(args = {}) {
    return this.call('pick_one', args);
  }
}
